            // 26-Jan-2017, tatu: [databind#935]: need to denote removal of
            Access acc = prop.removeNonVisible(inferMutators);
            if (!_forSerialization && (acc == Access.READ_ONLY)) {
                _collectIgnorals(prop.getName());
            }
        }
    }

