private FastMath fastMath;

@Before
public void setUp() {
    fastMath = new FastMath();
}

@After
public void tearDown() {
    fastMath = null;
}

@Test
public void testSqrt() {
    Assert.assertEquals(2.0, fastMath.sqrt(4.0), 0.0001);
    Assert.assertEquals(1.0, fastMath.sqrt(1.0), 0.0001);
    Assert.assertEquals(0.0, fastMath.sqrt(0.0), 0.0001);
    Assert.assertEquals(1.4142135623730951, fastMath.sqrt(2.0), 0.0001);
}

@Test
public void testCosh() {
    Assert.assertEquals(1.0, fastMath.cosh(0.0), 0.0001);
    Assert.assertEquals(2.0, fastMath.cosh(1.0), 0.0001);
    Assert.assertEquals(1.0, fastMath.cosh(-1.0), 0.0001);
}

@Test
public void testTanh() {
    Assert.assertEquals(0.0, fastMath.tanh(0.0), 0.0001);
    Assert.assertEquals(-1.0, fastMath.tanh(-1.0), 0.0001);
    Assert.assertEquals(1.0, fastMath.tanh(1.0), 0.0001);
}

@Test
public void testAtanh() {
    Assert.assertEquals(0.0, fastMath.atanh(0.0), 0.0001);
    Assert.assertEquals(1.0, fastMath.atanh(1.0), 0.0001);
    Assert.assertEquals(-1.0, fastMath.atanh(-1.0), 0.0001);
}

@Test
public void testRandom() {
    for (int i = 0; i < 1000; i++) {
        Assert.assertTrue(fastMath.random() <= 1.0);
    }
}

@Test
public void testExp() {
    Assert.assertEquals(2.718281828459045, fastMath.exp(1.0), 0.0001);
    Assert.assertEquals(1.0, fastMath.exp(0.0), 0.0001);
    Assert.assertEquals(0.0, fastMath.exp(-1.0), 0.0001);
}

@Test
public void testExpm1() {
    Assert.assertEquals(2.718281828459045 - 1.0, fastMath.expm1(1.0), 0.0001);
    Assert.assertEquals(1.0 - 1.0, fastMath.expm1(0.0), 0.0001);
    Assert.assertEquals(0.0, fastMath.expm1(-1.0), 0.0001);
}

@Test
public void testLog() {
    Assert.assertEquals(0.0, fastMath.log(1.0), 0.0001);
    Assert.assertEquals(0.0, fastMath.log(1.0), 0.0001);
    Assert.assertEquals(1.0, fastMath.log(Math.E), 0.0001);
}

